import{_ as t,c as h,o as i,a2 as a}from"./chunks/framework.B7el9cAC.js";const d=JSON.parse('{"title":"Mục 3.4 – Học máy (Machine Learning)","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-3/3.4-hoc-may.md","filePath":"chuong-3/3.4-hoc-may.md","lastUpdated":1775300925000}'),o={name:"chuong-3/3.4-hoc-may.md"};function c(g,n,r,l,e,u){return i(),h("div",null,[...n[0]||(n[0]=[a('<h1 id="muc-3-4-–-hoc-may-machine-learning" tabindex="-1">Mục 3.4 – Học máy (Machine Learning) <a class="header-anchor" href="#muc-3-4-–-hoc-may-machine-learning" aria-label="Permalink to &quot;Mục 3.4 – Học máy (Machine Learning)&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p>Bạn có biết rằng <strong>email rác (spam)</strong> không bị chặn bởi một danh sách từ cấm cố định? Nó bị chặn bởi một chương trình đã <strong>tự học</strong> từ hàng triệu email mà người dùng đã đánh dấu là spam. Chương trình đó là một ví dụ điển hình của <strong>học máy</strong>.</p><p><strong>Học máy là gì theo nghĩa đơn giản nhất?</strong> Thay vì lập trình cứng từng quy tắc (&quot;nếu email có từ &#39;trúng thưởng&#39; thì chặn&quot;), bạn cho máy tính <strong>tự rút ra quy tắc</strong> từ dữ liệu mẫu. Máy tính &quot;học&quot; như một học sinh — xem ví dụ, nhận ra mẫu, rồi áp dụng vào trường hợp mới.</p><p><strong>Ví dụ đời thực:</strong></p><ul><li>🏠 <strong>Tại nhà:</strong> Camera an ninh học nhận diện thành viên gia đình, tự cảnh báo khi có người lạ.</li><li>☕ <strong>Tại quán cafe:</strong> Hệ thống POS dự đoán nguyên liệu cần nhập kho dựa trên lịch sử bán hàng.</li><li>🏫 <strong>Tại trường:</strong> Phần mềm phát hiện đạo văn học mẫu văn bản của từng học sinh để nhận ra bất thường.</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="hoc-may-machine-learning-la-gi" tabindex="-1">Học máy (Machine Learning) là gì? <a class="header-anchor" href="#hoc-may-machine-learning-la-gi" aria-label="Permalink to &quot;Học máy (Machine Learning) là gì?&quot;">​</a></h3><p><strong>Học máy (Machine Learning – ML)</strong> là nhánh của AI cho phép máy tính <strong>tự cải thiện hiệu năng</strong> thông qua kinh nghiệm (dữ liệu) mà <strong>không cần lập trình tường minh</strong> cho từng tình huống cụ thể.</p><p>Thay vì:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lập trình viên viết quy tắc → Máy tính áp dụng quy tắc → Kết quả</span></span></code></pre></div><p>Học máy làm:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dữ liệu + Kết quả mong muốn → Thuật toán học → Quy tắc (mô hình) → Áp dụng cho dữ liệu mới</span></span></code></pre></div><h3 id="ba-loai-hoc-may-chinh" tabindex="-1">Ba loại học máy chính <a class="header-anchor" href="#ba-loai-hoc-may-chinh" aria-label="Permalink to &quot;Ba loại học máy chính&quot;">​</a></h3><h4 id="_1-hoc-co-giam-sat-supervised-learning" tabindex="-1">1. Học có giám sát (Supervised Learning) <a class="header-anchor" href="#_1-hoc-co-giam-sat-supervised-learning" aria-label="Permalink to &quot;1. Học có giám sát (Supervised Learning)&quot;">​</a></h4><ul><li><strong>Đặc điểm:</strong> Dữ liệu huấn luyện có nhãn (đã biết đúng/sai)</li><li><strong>Cách học:</strong> Máy học từ cặp (đầu vào → đầu ra mong muốn) đã biết</li><li><strong>Ví dụ:</strong> Nhận diện ảnh chó/mèo khi đã có 10.000 ảnh được gán nhãn sẵn</li><li><strong>Ứng dụng thực tế:</strong> Lọc spam, dự đoán giá nhà, chẩn đoán bệnh qua ảnh X-quang</li></ul><h4 id="_2-hoc-khong-giam-sat-unsupervised-learning" tabindex="-1">2. Học không giám sát (Unsupervised Learning) <a class="header-anchor" href="#_2-hoc-khong-giam-sat-unsupervised-learning" aria-label="Permalink to &quot;2. Học không giám sát (Unsupervised Learning)&quot;">​</a></h4><ul><li><strong>Đặc điểm:</strong> Dữ liệu không có nhãn</li><li><strong>Cách học:</strong> Máy tự tìm ra cấu trúc, nhóm, mẫu ẩn trong dữ liệu</li><li><strong>Ví dụ:</strong> Nhóm khách hàng theo hành vi mua sắm mà không biết trước nhóm là gì</li><li><strong>Ứng dụng thực tế:</strong> Phân đoạn thị trường, phát hiện gian lận tài chính, nén dữ liệu</li></ul><h4 id="_3-hoc-tang-cuong-reinforcement-learning" tabindex="-1">3. Học tăng cường (Reinforcement Learning) <a class="header-anchor" href="#_3-hoc-tang-cuong-reinforcement-learning" aria-label="Permalink to &quot;3. Học tăng cường (Reinforcement Learning)&quot;">​</a></h4><ul><li><strong>Đặc điểm:</strong> Máy học qua thử và sai, nhận điểm thưởng/phạt</li><li><strong>Cách học:</strong> Giống như dạy con chó bằng phần thưởng — làm đúng được thưởng, làm sai bị phạt</li><li><strong>Ví dụ:</strong> AI học chơi cờ vua bằng cách tự chơi hàng triệu ván, thắng được điểm thưởng</li><li><strong>Ứng dụng thực tế:</strong> AlphaGo (cờ vây), xe tự lái học cách điều hướng, robot học cách đi đứng</li></ul><h3 id="qua-trinh-hoc-cua-may" tabindex="-1">Quá trình học của máy <a class="header-anchor" href="#qua-trinh-hoc-cua-may" aria-label="Permalink to &quot;Quá trình học của máy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bước</th><th>Tên</th><th>Mô tả</th></tr></thead><tbody><tr><td>1</td><td>Thu thập dữ liệu</td><td>Tập hợp dữ liệu huấn luyện có chất lượng</td></tr><tr><td>2</td><td>Tiền xử lý</td><td>Làm sạch, chuẩn hóa, loại bỏ nhiễu</td></tr><tr><td>3</td><td>Chọn mô hình</td><td>Chọn thuật toán phù hợp với bài toán</td></tr><tr><td>4</td><td>Huấn luyện</td><td>Chạy thuật toán trên dữ liệu để học tham số</td></tr><tr><td>5</td><td>Đánh giá</td><td>Kiểm tra độ chính xác trên dữ liệu chưa thấy</td></tr><tr><td>6</td><td>Tinh chỉnh</td><td>Điều chỉnh để cải thiện kết quả</td></tr><tr><td>7</td><td>Triển khai</td><td>Đưa mô hình vào sử dụng thực tế</td></tr></tbody></table><h3 id="deep-learning-hoc-sau-la-gi" tabindex="-1">Deep Learning (Học sâu) là gì? <a class="header-anchor" href="#deep-learning-hoc-sau-la-gi" aria-label="Permalink to &quot;Deep Learning (Học sâu) là gì?&quot;">​</a></h3><p><strong>Deep Learning</strong> là nhánh nâng cao của học máy sử dụng <strong>mạng nơ-ron nhân tạo</strong> nhiều lớp (deep neural networks), lấy cảm hứng từ cách não người hoạt động.</p><ul><li><strong>Điểm mạnh:</strong> Rất hiệu quả với dữ liệu phức tạp như ảnh, âm thanh, văn bản</li><li><strong>Điểm yếu:</strong> Cần lượng dữ liệu và sức mạnh tính toán rất lớn</li><li><strong>Ứng dụng:</strong> Nhận diện giọng nói (Siri), dịch ngôn ngữ (Google Dịch), tạo ảnh từ văn bản</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="hoc-may-hoat-đong-nhu-the-nao-thuc-su" tabindex="-1">Học máy hoạt động như thế nào thực sự? <a class="header-anchor" href="#hoc-may-hoat-đong-nhu-the-nao-thuc-su" aria-label="Permalink to &quot;Học máy hoạt động như thế nào thực sự?&quot;">​</a></h3><p>Hãy tưởng tượng bạn đang học nhận biết trái cây:</p><ol><li><strong>Dữ liệu:</strong> Bạn được xem 1.000 ảnh táo (gán nhãn &quot;táo&quot;) và 1.000 ảnh cam (gán nhãn &quot;cam&quot;)</li><li><strong>Đặc trưng:</strong> Não bạn tự học ra: táo = tròn + đỏ/xanh lá + cuống nhỏ, cam = tròn + cam + vỏ sần</li><li><strong>Mô hình:</strong> Bộ quy tắc ngầm định hình thành trong não</li><li><strong>Dự đoán:</strong> Khi thấy quả mới, não áp dụng quy tắc đã học → nhận ra đó là táo hay cam</li></ol><p><strong>Máy tính làm y như vậy</strong> — nhưng thay vì não người, đó là ma trận số và phép tính toán học. Những &quot;đặc trưng&quot; máy học ra không phải là từ ngữ mô tả mà là <strong>các con số đặc trưng</strong> (feature vectors).</p><h3 id="tai-sao-can-nhieu-du-lieu" tabindex="-1">Tại sao cần nhiều dữ liệu? <a class="header-anchor" href="#tai-sao-can-nhieu-du-lieu" aria-label="Permalink to &quot;Tại sao cần nhiều dữ liệu?&quot;">​</a></h3><p>Giống như một học sinh cần làm nhiều bài tập để giỏi — máy cần nhiều ví dụ để nhận ra mẫu chính xác. Nếu chỉ thấy 5 ảnh chó, máy có thể nghĩ &quot;chó = con vật màu nâu&quot; — cho đến khi thấy chó trắng thì nhầm.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="huan-luyen-mo-hinh-nhan-dien-spam" tabindex="-1">Huấn luyện mô hình nhận diện spam <a class="header-anchor" href="#huan-luyen-mo-hinh-nhan-dien-spam" aria-label="Permalink to &quot;Huấn luyện mô hình nhận diện spam&quot;">​</a></h3><ol><li><strong>Thu thập dữ liệu:</strong> 10.000 email đã được gán nhãn: 5.000 spam, 5.000 không spam</li><li><strong>Trích xuất đặc trưng:</strong> Đếm tần suất từ, địa chỉ người gửi, có link không, có file đính kèm không</li><li><strong>Huấn luyện:</strong> Thuật toán học phân biệt email spam dựa trên các đặc trưng đó</li><li><strong>Kiểm tra:</strong> Thử với 1.000 email chưa thấy — đạt 95% chính xác</li><li><strong>Triển khai:</strong> Tích hợp vào hệ thống email</li><li><strong>Cập nhật liên tục:</strong> Khi người dùng đánh dấu spam mới → dữ liệu mới → mô hình được tái huấn luyện</li></ol><h3 id="xe-tu-lai-hoc-lai-xe" tabindex="-1">Xe tự lái học lái xe <a class="header-anchor" href="#xe-tu-lai-hoc-lai-xe" aria-label="Permalink to &quot;Xe tự lái học lái xe&quot;">​</a></h3><ol><li><strong>Thu thập dữ liệu:</strong> Hàng triệu giờ video lái xe với quyết định của tài xế người</li><li><strong>Nhận diện đặc trưng:</strong> Làn đường, biển báo, phương tiện khác, người đi bộ</li><li><strong>Học quyết định:</strong> Khi nào tăng tốc, phanh, rẽ, nhường đường</li><li><strong>Thử nghiệm ảo:</strong> Mô phỏng hàng triệu tình huống nguy hiểm trong máy tính</li><li><strong>Thử nghiệm thực tế:</strong> Chạy thật trên đường có giám sát</li><li><strong>Cải thiện liên tục:</strong> Tai nạn/tình huống bất ngờ → học từ lỗi → cải thiện</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-du-đoan-thoi-tiet" tabindex="-1">Ví dụ 1 – Cơ bản: Dự đoán thời tiết <a class="header-anchor" href="#vi-du-1-–-co-ban-du-đoan-thoi-tiet" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Dự đoán thời tiết&quot;">​</a></h3><p>Mô hình học máy được huấn luyện với 30 năm dữ liệu thời tiết (nhiệt độ, độ ẩm, áp suất không khí, lượng mưa hôm trước…) và thời tiết thực tế hôm sau. Sau khi học, nó có thể dự đoán: &quot;Ngày mai có 78% khả năng mưa&quot; dựa trên điều kiện thời tiết hôm nay.</p><h3 id="vi-du-2-–-đoi-thuc-spotify-goi-y-nhac" tabindex="-1">Ví dụ 2 – Đời thực: Spotify gợi ý nhạc <a class="header-anchor" href="#vi-du-2-–-đoi-thuc-spotify-goi-y-nhac" aria-label="Permalink to &quot;Ví dụ 2 – Đời thực: Spotify gợi ý nhạc&quot;">​</a></h3><p>Spotify dùng học máy để:</p><ul><li>Phân tích âm học của bài nhạc (nhịp điệu, nhạc cụ, tempo, tông giọng)</li><li>So sánh sở thích của bạn với hàng triệu người dùng khác</li><li>Dự đoán bài hát nào bạn sẽ thích nhất</li></ul><p>→ Playlist &quot;Discover Weekly&quot; mỗi thứ Hai chính là kết quả của hàng triệu phép tính học máy.</p><h3 id="vi-du-3-–-nang-cao-alphago-đanh-bai-nha-vo-đich-co-vay" tabindex="-1">Ví dụ 3 – Nâng cao: AlphaGo đánh bại nhà vô địch cờ vây <a class="header-anchor" href="#vi-du-3-–-nang-cao-alphago-đanh-bai-nha-vo-đich-co-vay" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: AlphaGo đánh bại nhà vô địch cờ vây&quot;">​</a></h3><p>AlphaGo của Google DeepMind dùng <strong>học tăng cường</strong>:</p><ul><li>Ban đầu học từ hàng triệu ván cờ của người chơi</li><li>Sau đó tự chơi hàng triệu ván với chính mình</li><li>Mỗi nước đi thắng → điểm thưởng, nước đi thua → điểm phạt</li><li>Sau hàng tỷ lần thử, AlphaGo tìm ra các chiến thuật mà <strong>chưa người chơi cờ nào từng nghĩ ra</strong></li><li>Năm 2016, AlphaGo đánh bại Lee Sedol — nhà vô địch cờ vây thế giới — 4-1</li></ul><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="ba-loai-hoc-may" tabindex="-1">Ba loại học máy <a class="header-anchor" href="#ba-loai-hoc-may" aria-label="Permalink to &quot;Ba loại học máy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Học có giám sát</th><th>Học không giám sát</th><th>Học tăng cường</th></tr></thead><tbody><tr><td>Dữ liệu</td><td>Có nhãn (labeled)</td><td>Không nhãn (unlabeled)</td><td>Phản hồi thưởng/phạt</td></tr><tr><td>Mục tiêu</td><td>Dự đoán/phân loại</td><td>Tìm cấu trúc/nhóm</td><td>Tối đa hóa phần thưởng</td></tr><tr><td>Ví dụ</td><td>Lọc spam, chẩn đoán bệnh</td><td>Phân nhóm khách hàng</td><td>AlphaGo, xe tự lái</td></tr><tr><td>Khó khăn</td><td>Cần nhiều dữ liệu có nhãn (tốn công gán)</td><td>Khó đánh giá kết quả</td><td>Cần nhiều vòng thử</td></tr></tbody></table><h3 id="machine-learning-vs-deep-learning-vs-ai" tabindex="-1">Machine Learning vs Deep Learning vs AI <a class="header-anchor" href="#machine-learning-vs-deep-learning-vs-ai" aria-label="Permalink to &quot;Machine Learning vs Deep Learning vs AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Khái niệm</th><th>Mô tả</th><th>Phạm vi</th></tr></thead><tbody><tr><td>AI (Trí tuệ nhân tạo)</td><td>Khái niệm rộng — máy làm việc đòi hỏi trí tuệ người</td><td>Rộng nhất</td></tr><tr><td>Machine Learning (Học máy)</td><td>AI học từ dữ liệu</td><td>Nằm trong AI</td></tr><tr><td>Deep Learning (Học sâu)</td><td>ML dùng mạng nơ-ron nhiều lớp</td><td>Nằm trong ML</td></tr></tbody></table><p><em>Hình ảnh tóm tắt:</em> AI ⊃ Machine Learning ⊃ Deep Learning</p><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li><strong>Học máy (ML)</strong> = máy tính tự học từ dữ liệu, không cần lập trình từng quy tắc cụ thể</li><li><strong>Học có giám sát</strong> = dữ liệu có nhãn → học phân loại/dự đoán (spam, chẩn đoán bệnh)</li><li><strong>Học không giám sát</strong> = dữ liệu không nhãn → tự tìm cấu trúc/nhóm (phân khúc khách hàng)</li><li><strong>Học tăng cường</strong> = học qua thử và sai, tối đa phần thưởng (AlphaGo, xe tự lái)</li><li><strong>Deep Learning</strong> = ML với mạng nơ-ron nhiều lớp, hiệu quả với ảnh/âm thanh/văn bản</li><li><strong>Mô hình</strong> = bộ quy tắc/tham số mà máy học được từ dữ liệu</li><li>Học máy cần <strong>dữ liệu nhiều và chất lượng</strong> — dữ liệu xấu → mô hình xấu</li><li>AI ⊃ Machine Learning ⊃ Deep Learning (học sâu là tập con của học máy)</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><p><strong>Câu 1 (Dễ):</strong> Phân biệt &quot;lập trình truyền thống&quot; và &quot;học máy&quot; theo cách tiếp cận giải quyết vấn đề.</p><blockquote><p><strong>Đáp án:</strong></p><ul><li><strong>Lập trình truyền thống:</strong> Lập trình viên viết tường minh từng quy tắc → Máy tính áp dụng → Ra kết quả.</li><li><strong>Học máy:</strong> Cung cấp dữ liệu có kết quả đã biết → Thuật toán tự học quy tắc → Áp dụng cho dữ liệu mới.</li><li><strong>Điểm khác biệt:</strong> Học máy không cần biết trước quy tắc — máy tự tìm ra.</li></ul></blockquote><hr><p><strong>Câu 2 (Dễ):</strong> Cho ba ứng dụng sau, hãy xác định loại học máy phù hợp nhất cho mỗi ứng dụng: (a) phân loại email spam, (b) tìm nhóm khách hàng tương tự nhau, (c) huấn luyện robot đi trong mê cung.</p><blockquote><p><strong>Đáp án:</strong></p><ul><li>(a) <strong>Học có giám sát</strong> — có dữ liệu mẫu đã gán nhãn spam/không spam.</li><li>(b) <strong>Học không giám sát</strong> — không biết trước các nhóm, máy tự tìm cấu trúc.</li><li>(c) <strong>Học tăng cường</strong> — robot học qua thử sai, đến đích được thưởng, đâm tường bị phạt.</li></ul></blockquote><hr><p><strong>Câu 3 (Trung bình):</strong> Mô tả 4 bước cơ bản trong quá trình xây dựng một mô hình học máy.</p><blockquote><p><strong>Đáp án:</strong></p><ol><li><strong>Thu thập và tiền xử lý dữ liệu:</strong> Tập hợp dữ liệu, làm sạch, chuẩn hóa.</li><li><strong>Chọn và huấn luyện mô hình:</strong> Chọn thuật toán phù hợp, chạy trên dữ liệu huấn luyện.</li><li><strong>Đánh giá mô hình:</strong> Kiểm tra độ chính xác trên dữ liệu chưa thấy (test set).</li><li><strong>Tinh chỉnh và triển khai:</strong> Điều chỉnh tham số cho tốt hơn, rồi đưa vào sử dụng thực tế.</li></ol></blockquote><hr><p><strong>Câu 4 (Trung bình):</strong> Tại sao chất lượng dữ liệu huấn luyện lại quan trọng trong học máy? Cho ví dụ về tác hại của dữ liệu kém chất lượng.</p><blockquote><p><strong>Đáp án:</strong> Mô hình học máy chỉ tốt bằng dữ liệu nó học từ đó — &quot;garbage in, garbage out&quot;. Ví dụ: Một hệ thống nhận diện khuôn mặt được huấn luyện chủ yếu trên ảnh người da trắng sẽ nhận diện kém hơn với người da đen — vì dữ liệu không đa dạng. Dữ liệu thiên vị → mô hình thiên vị → kết quả phân biệt đối xử.</p></blockquote><hr><p><strong>Câu 5 (Ứng dụng):</strong> Một bệnh viện muốn dùng học máy để chẩn đoán sớm bệnh tiểu đường từ kết quả xét nghiệm máu. Hãy mô tả: (a) loại học máy phù hợp, (b) dữ liệu cần thu thập, (c) một rủi ro cần lưu ý.</p><blockquote><p><strong>Đáp án gợi ý:</strong></p><ul><li><strong>(a) Học có giám sát:</strong> Vì có dữ liệu lịch sử bệnh nhân (kết quả xét nghiệm + chẩn đoán thực tế của bác sĩ).</li><li><strong>(b) Dữ liệu cần thu thập:</strong> Chỉ số đường huyết, HbA1c, BMI, tuổi, tiền sử gia đình, kết quả xét nghiệm khác + nhãn &quot;có/không có tiểu đường&quot; do bác sĩ xác nhận.</li><li><strong>(c) Rủi ro:</strong> Mô hình có thể cho kết quả dương tính giả (chẩn đoán nhầm bệnh) hoặc âm tính giả (bỏ sót bệnh). Cần bác sĩ xem xét kết quả AI — không được để AI ra quyết định y tế độc lập.</li></ul></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lỗi thường gặp</th><th>Cách hiểu đúng</th></tr></thead><tbody><tr><td>Nhầm học máy là AI viết code tự động</td><td>ML không viết code — nó điều chỉnh tham số số học dựa trên dữ liệu.</td></tr><tr><td>Nghĩ mô hình học máy &quot;hiểu&quot; dữ liệu</td><td>Mô hình chỉ nhận ra mẫu thống kê — không &quot;hiểu&quot; theo nghĩa con người.</td></tr><tr><td>Cho rằng nhiều dữ liệu hơn luôn tốt hơn</td><td>Dữ liệu nhiều nhưng kém chất lượng, thiên lệch, hoặc không liên quan sẽ làm mô hình kém.</td></tr><tr><td>Nhầm Deep Learning = Machine Learning</td><td>Deep Learning là một loại của Machine Learning, không phải đồng nghĩa.</td></tr><tr><td>Nghĩ học máy chỉ dùng trong IT</td><td>Học máy được dùng trong y tế, tài chính, nông nghiệp, giáo dục, và rất nhiều lĩnh vực khác.</td></tr></tbody></table>',81)])])}const m=t(o,[["render",c]]);export{d as __pageData,m as default};
